<script setup lang="ts">
import {ref} from 'vue'
import {api} from './api'
import {yuanToCents} from './amount.mjs'
const props=defineProps<{shop:any,clock:any}>(),emit=defineEmits(['close','created'])
const title=ref(''),subtitle=ref(''),rules=ref(''),pay=ref(''),face=ref(''),kind=ref(0),stock=ref(100),begin=ref(''),end=ref(''),agreed=ref(false),busy=ref(false),error=ref(''),uncertain=ref(false)
async function save(){if(busy.value||uncertain.value)return;error.value='';let payload:any
try{const payValue=yuanToCents(pay.value),actualValue=yuanToCents(face.value);if(!actualValue||payValue>actualValue)throw new Error('券面金额应大于0，售价不能高于券面金额');if(kind.value===1&&(!begin.value||!end.value||end.value<=begin.value))throw new Error('请填写有效的秒杀起止时间');payload={title:title.value.trim(),subTitle:subtitle.value.trim(),rules:rules.value.trim(),payValue,actualValue,type:kind.value,...(kind.value===1?{stock:stock.value,beginTime:begin.value+':00',endTime:end.value+':00'}:{})}}catch(e){error.value=(e as Error).message;return}
busy.value=true;try{await api(`/api/catalog/shops/${props.shop.id}/vouchers`,'POST',payload);emit('created');emit('close')}catch(e){error.value=(e as Error).message;if(/fetch|network|网络|暂时不可用/i.test(error.value)){uncertain.value=true;error.value+='。保存结果尚不确定，请关闭并刷新商品列表核实，勿重复添加。'}}finally{busy.value=false}}
</script>
<template><div class="overlay"><section class="modal wide" role="dialog" aria-modal="true" aria-labelledby="voucher-create-title"><button class="close" aria-label="关闭窗口" :disabled="busy" @click="emit('close')">×</button><div class="eyebrow">DEMO CATALOG MANAGEMENT</div><h2 id="voucher-create-title">添加演示代金券</h2><p class="muted">关联店铺：{{shop.name}}</p><p class="small muted">新增后会保存到点评数据库，可用于 Agent 查询和下单联调；标题会自动加上「【演示】」。</p><form @submit.prevent="save"><div class="tabs"><button type="button" :disabled="busy" :class="{active:kind===0}" @click="kind=0">普通券 / 免费券</button><button type="button" :disabled="busy" :class="{active:kind===1}" @click="kind=1">限时秒杀券</button></div><fieldset :disabled="busy||uncertain" style="border:0;padding:0;margin:0"><label>券标题<input v-model="title" required maxlength="96" placeholder="例如：100元代金券"></label><label>副标题（选填）<input v-model="subtitle" maxlength="200" placeholder="例如：工作日到店可用"></label><div class="inline"><label>售价（元）<input v-model="pay" type="text" inputmode="decimal" required pattern="(0|[1-9][0-9]*)(\.[0-9]{1,2})?" placeholder="例如：89；免费券填0"></label><label>券面金额（元）<input v-model="face" type="text" inputmode="decimal" required pattern="(0|[1-9][0-9]*)(\.[0-9]{1,2})?" placeholder="例如：100"></label></div><label>使用规则<textarea v-model="rules" required rows="3" maxlength="1000" placeholder="填写适用门店、可用时间、是否可叠加等；注明仅供本地演示。"/></label><template v-if="kind===1"><label>秒杀库存<input v-model.number="stock" type="number" min="1" max="100000" required></label><div class="inline"><label>开始时间<input v-model="begin" type="datetime-local" step="60" required></label><label>结束时间<input v-model="end" type="datetime-local" step="60" required></label></div><p class="small muted">起止时间请按点评服务时区 {{clock.server_zone}} 填写，服务时间：{{clock.server_time}}。普通券没有限量库存。</p></template><label class="check"><input v-model="agreed" type="checkbox" required>我确认添加的是本地演示商品，不代表真实商家活动</label></fieldset><p class="error" role="alert" v-if="error">{{error}}</p><div class="actions"><button type="button" class="outline" :disabled="busy" @click="emit('close')">取消</button><button class="primary" :disabled="busy||!agreed||uncertain">{{busy?'正在保存…':'确认添加'}}</button></div></form></section></div></template>
